# The written procedure: verify identity first, then act,
# then notify the user and their manager.
SENSITIVE = {"reset_password", "reset_mfa", "change_sms_number"}
NOTIFY = {"notify_user", "notify_manager"}

def audit(steps):
    problems, verified = [], False
    for step in steps:
        if step == "verify_identity":
            verified = True
        elif step in SENSITIVE and not verified:
            problems.append(f"{step} with no identity check")
    if set(steps) & SENSITIVE:
        missing = NOTIFY - set(steps)
        if missing:
            problems.append("missing " + ", ".join(sorted(missing)))
    return problems or ["ok"]

tickets = {
    "HD-101": ["verify_identity", "reset_password",
               "notify_user", "notify_manager"],
    "HD-102": ["reset_password", "reset_mfa", "reset_mfa",
               "change_sms_number"],
}
for tid, steps in tickets.items():
    for p in audit(steps):
        print(tid, p)

# Output:
# HD-101 ok
# HD-102 reset_password with no identity check
# HD-102 reset_mfa with no identity check
# HD-102 reset_mfa with no identity check
# HD-102 change_sms_number with no identity check
# HD-102 missing notify_manager, notify_user

# Proofs a caller can offer, and whether an attacker can usually get them.
PUBLIC = {"name", "employee_id", "date_of_birth", "manager_name",
          "last4_ssn", "callback_number_from_caller"}
STRONG = {"passkey_signin",            # signs in with an existing factor
          "video_match_to_id_on_file", # on-camera, compared with HR photo
          "in_person_with_badge"}
OUT_OF_BAND = {"callback_to_number_on_file", "manager_approves_in_ticket"}

def decide(request, proofs, privileged):
    proofs = set(proofs)
    if request == "password_reset" and "passkey_signin" in proofs:
        return "allow: self-service, caller already proved a factor"
    if not proofs & (STRONG | OUT_OF_BAND):
        n = len(proofs & PUBLIC)
        return f"deny: {n} facts, all of them easy to look up or buy"
    if privileged and not (proofs & STRONG and proofs & OUT_OF_BAND):
        return "deny: privileged account needs strong AND out-of-band"
    return "allow: then notify user on old factor and alert the SOC"

calls = [
    ("mfa_reset", ["name", "employee_id", "date_of_birth"], False),
    ("mfa_reset", ["callback_to_number_on_file"], False),
    ("mfa_reset", ["video_match_to_id_on_file"], True),
    ("mfa_reset", ["video_match_to_id_on_file",
                   "manager_approves_in_ticket"], True),
]
for req, proofs, priv in calls:
    print("admin" if priv else "user ", " + ".join(proofs))
    print("      " + decide(req, proofs, priv))

# (minute, badge, door, event)  -- a simplified access-control log
log = [
    (480, "B17", "lobby-in",  "granted"),
    (481, "B17", "lab-in",    "granted"),
    (482, "lab", "lab-door",  "held_open_45s"),
    (530, "B22", "lab-out",   "granted"),   # B22 never badged into the lab
    (600, "B31", "hq-in",     "granted"),
    (604, "B31", "depot-in",  "granted"),   # depot is 40 minutes away
    (700, "B09", "lab-in",    "denied"),
    (701, "B09", "lab-in",    "denied"),
    (702, "B09", "lab-in",    "denied"),
]
TRAVEL = {("hq", "depot"): 40}              # minutes between sites

inside, last_seen, denied, alerts = set(), {}, {}, []
for t, who, door, ev in log:
    site, way = door.rsplit("-", 1)
    if ev.startswith("held_open"):
        alerts.append(f"{t}: {site} door {ev}: someone may have followed in")
    elif ev == "denied":
        denied[who] = denied.get(who, 0) + 1
        if denied[who] == 3:
            alerts.append(f"{t}: {who} denied 3 times at {site}")
    elif way == "out" and (who, site) not in inside:
        alerts.append(f"{t}: {who} left {site} without badging in (tailgated?)")
    else:
        if who in last_seen:
            t0, s0 = last_seen[who]
            need = TRAVEL.get((s0, site)) or TRAVEL.get((site, s0)) or 0
            if t - t0 < need:
                alerts.append(f"{t}: {who} at {s0} then {site} in {t - t0} min (cloned?)")
        last_seen[who] = (t, site)
        if way == "in":
            inside.add((who, site))
for a in alerts:
    print(a)
